target.css:
:root {
  --paper: #fffdf7;
  --ink: #1f3446;
  --muted: #70808b;
  --line: #d8e0df;
  --aqua: #dff1ed;
  --aqua-deep: #237b78;
  --yellow: #f7d766;
  --yellow-pale: #fff4c9;
  --navy: #294f68;
}

* {
  box-sizing: border-box;
}

.repair-ticket {
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.ticket-header {
  display: flex;
  align-items: center;
  gap: 11px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
  background: var(--aqua);
}

.mark {
  display: grid;
  width: 36px;
  height: 36px;
  place-items: center;
  border-radius: 12px;
  background: var(--paper);
  font-size: 20px;
}

.ticket-title {
  flex: 1;
}

.ticket-title p,
.ticket-title h1,
.item-copy h2,
.item-copy p,
.note {
  margin: 0;
}

.ticket-title p {
  color: var(--aqua-deep);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.9px;
}

.ticket-title h1 {
  margin-top: 2px;
  font-size: 19px;
  line-height: 1.1;
}

.status {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--yellow);
  color: var(--navy);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.6px;
}

.ticket-body {
  padding: 14px 16px 12px;
}

.item-row {
  display: flex;
  align-items: center;
  gap: 10px;
}

.umbrella {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--navy);
  font-size: 26px;
  line-height: 1;
}

.item-copy h2 {
  font-size: 16px;
  line-height: 1.2;
}

.item-copy p {
  margin-top: 3px;
  color: var(--muted);
  font-size: 12px;
}

.details {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 7px;
  margin-top: 14px;
}

.detail {
  min-width: 0;
  padding: 8px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: var(--paper);
}

.detail span,
.detail strong {
  display: block;
}

.detail span {
  color: var(--muted);
  font-size: 10px;
  line-height: 1.2;
}

.detail strong {
  margin-top: 4px;
  color: var(--navy);
  font-size: 12px;
  line-height: 1.1;
}

.note {
  margin-top: 12px;
  padding: 8px 10px;
  border-left: 3px solid var(--yellow);
  border-radius: 4px;
  background: var(--yellow-pale);
  font-size: 12px;
  line-height: 1.35;
}

.ticket-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 16px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 11px;
}

.claim {
  font-weight: 700;
}

.ready {
  color: var(--aqua-deep);
  font-weight: 700;
  white-space: nowrap;
}

